import React, { useState } from "react";
import axios from "axios";
import { API } from "../config";

function Home() {
  const [vehicle, setVehicle] = useState("");
  const [results, setResults] = useState([]);

  const searchChallan = async () => {
    if (!vehicle.trim()) return alert("Enter vehicle number!");
    try {
      const res = await axios.get(`${API}/challan/vehicle/${vehicle}`);
      setResults(res.data);
      if (res.data.length === 0) alert("No challans found.");
    } catch (err) {
      console.error(err);
      alert("Error fetching challans");
    }
  };

  return (
    <div style={{ padding: 20 }}>
      <h2>Traffic Challan Search</h2>
      <input
        placeholder="Vehicle Number"
        value={vehicle}
        onChange={(e) => setVehicle(e.target.value)}
      />
      <button onClick={searchChallan}>Search</button>

      {results.length > 0 && (
        <table border="1" cellPadding="6" style={{ marginTop: 10 }}>
          <thead>
            <tr>
              <th>#</th>
              <th>Vehicle</th>
              <th>Cause</th>
              <th>Fine</th>
              <th>Status</th>
              <th>Issue Date</th>
              <th>Due Date</th>
              <th>Address</th>
            </tr>
          </thead>
          <tbody>
            {results.map((c, i) => (
              <tr key={c._id}>
                <td>{i + 1}</td>
                <td>{c.vehicleNumber}</td>
                <td>{c.cause}</td>
                <td>{c.fine}</td>
                <td>{c.status}</td>
                <td>{c.issueDate}</td>
                <td>{c.dueDate}</td>
                <td>{c.address}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

export default Home;
